const SPHINX = "sphinx";

const FREE_TYPES = 3;
const SCORE_WITHIN_FREE_TYPES = 2;
const BONUS_PER_EXTRA_TYPE = 2;

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

const countNonSphinxTypes = (army: Card[]): number =>
  new Set(army.filter((card) => !isSphinx(card)).map((card) => card.monster)).size;

