// The first type beyond the free allowance lifts the score by one, to 3. Every
// type after that adds the full bonus, giving the run 3, 5, 7, …
const SCORE_AT_FIRST_EXTRA_TYPE = SCORE_WITHIN_FREE_TYPES + 1;

const scorePerSphinx = (otherTypes: number): number =>
  otherTypes > FREE_TYPES
    ? SCORE_AT_FIRST_EXTRA_TYPE +
      BONUS_PER_EXTRA_TYPE * (otherTypes - FREE_TYPES - 1)
    : SCORE_WITHIN_FREE_TYPES;

const countSphinxes = (army: Card[]): number => army.filter(isSphinx).length;

export const scoreArmy = (army: Card[]): number =>
  countSphinxes(army) * scorePerSphinx(countNonSphinxTypes(army));
